def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    ion = [(props.get(x.get('element')) or {}).get('first_ionization_energy_eV') for x in sites]
    affinity = [(props.get(x.get('element')) or {}).get('electron_affinity_eV') or 0.0 for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    weight = 0.0
    for bond in s.get('neighbors') or []:
        i = bond.get('i', -1)
        j = bond.get('j', -1)
        d = bond.get('distance_A') or 0.0
        if 0 <= i < len(sites) and 0 <= j < len(sites) and 0.0 < d < 6.0:
            if ion[i] is not None and ion[j] is not None:
                w = occ[i] * occ[j] * (1.0 - d / 6.0) ** 2 / d
                cost = min(ion[i] - affinity[j], ion[j] - affinity[i])
                total += w * cost
                weight += w
    return total / max(weight, 1e-12)

def feature(s):
    if not s:
        return 0.0
    v = s.get('volume_per_atom_A3') or 0.0
    if v > 0.0:
        return v
    sites = s.get('sites') or []
    count = sum(max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites)
    volume = (s.get('lattice') or {}).get('volume_A3') or 0.0
    if count > 0.0 and volume > 0.0:
        return volume / count
    return 0.0

def feature(s):
    if not s:
        return 0.0
    volume = s.get('volume_per_atom_A3') or 0.0
    if volume <= 0.0:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        if fraction is not None and fraction > 0.0:
            radius = max(0.1, (props.get(element) or {}).get('covalent_radius_A') or 1.3)
            total += fraction * radius ** 3
            weight += fraction
    return 4.188790204786391 * total / (max(weight, 1e-12) * volume)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    en = [(props.get(x.get('element')) or {}).get('eneg') for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    weight = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 0.0 < d <= 6.0:
            reduced = d / (radii[i] + radii[j])
            if reduced <= 1.3:
                w = occ[i] * occ[j]
                weight += w
                if sites[i].get('element') == sites[j].get('element') and en[i] is not None and en[i] >= 2.4:
                    total += w
    return total / max(weight, 1e-12)

